PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://bigdata-rev.com/rider/ref#>
SELECT ?p ?id ?class WHERE {
  ?p a brick:ElectricPowerSensor ;
      brick:hasProperty brick:ElectricPower ;
      brick:feeds ?zone ;
      ref:hasTimeseriesId ?id .
  ?zone a brick:Zone .
  OPTIONAL { ?p rdfs:label ?lbl }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://bigdata-rev.com/rider/ref#>
SELECT ?b ?id WHERE {
  ?p a brick:ElectricPowerSensor ;
      brick:feeds ?b .
  ?b a brick:Building .
  ?p ref:hasTimeseriesId ?id .
  OPTIONAL { ?p rdfs:label ?lbl }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?p ?class WHERE {
  ?p a ?class .
  FILTER(?class != brick:Information)
  LIMIT 50
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
