  OPTIONAL { ?p rdfs:label ?lbl }
  OPTIONAL { ?p brick:hasLocation ?b }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?lbl WHERE {
  ?p rdfs:label ?lbl .
  FILTER(CONTAINS(str(?lbl), "light") || CONTAINS(str(?lbl), "Light") || CONTAINS(str(?lbl), "meter") || CONTAINS(str(?lbl), "power") || CONTAINS(str(?lbl), "electric"))
}

